<section class="panel">
 <h2>Plataforma de recetas</h2>
 <form method="post" class="form-grid"><input type="hidden" name="action" value="create">
 <?php foreach($fields as $key=>$field): ?>
 <label><?=e($field['label'])?><?php if($field['type']==='textarea'): ?><textarea name="<?=$key?>" required></textarea><?php elseif($field['type']==='select'): ?><select name="<?=$key?>" required><?php foreach($field['options'] as $opt): ?><option><?=e($opt)?></option><?php endforeach ?></select><?php else: ?><input type="<?=$field['type']?>" name="<?=$key?>" <?= $field['type']==='number'?'min="0" step="0.01"':'' ?> required><?php endif ?></label>
 <?php endforeach ?><button class="btn" type="submit">Guardar</button></form></section>
 <section class="panel"><div class="section-title"><h2>Registros</h2><?php if($current==='expenses'): ?><form method="get"><input type="hidden" name="page" value="expenses"><input type="month" name="month" value="<?=e($month)?>"><button class="btn secondary">Ver mes</button></form><?php elseif(in_array($current,['notes','recipes'])): ?><form method="get"><input type="hidden" name="page" value="<?=$current?>"><input name="q" placeholder="Buscar..." value="<?=e($query??'')?>"><button class="btn secondary">Buscar</button></form><?php endif ?></div>
 <?php if($current==='expenses'): ?><div class="summary"><small>Total del mes</small><strong>$<?=number_format($sum,0,',','.')?> COP</strong></div><?php endif ?>
 <?php if(!$items): ?><p class="empty">Todavía no hay registros. Agrega el primero usando el formulario.</p><?php else: ?><div class="records"><?php foreach($items as $item): ?><article class="record">
 <div class="record-content">
 <?php if($current==='tasks'): ?><h3 class="<?=!empty($item['done'])?'done':''?>"><?=e($item['task']??'')?></h3><p>Prioridad: <?=e($item['priority']??'')?> · <?=!empty($item['done'])?'Completada':'Pendiente'?></p>
 <?php elseif($current==='expenses'): ?><h3><?=e($item['concept']??'')?></h3><p><?=e($item['category']??'')?> · <?=e($item['date']??'')?></p><strong>$<?=number_format((float)($item['amount']??0),0,',','.')?> COP</strong>
 <?php elseif($current==='bookings'): ?><h3><?=e($item['client']??'')?> — <?=e($item['service']??'')?></h3><p><?=e($item['date']??'')?> a las <?=e($item['time']??'')?></p>
 <?php elseif($current==='notes'): ?><h3><?=e($item['title']??'')?></h3><p class="muted"><?=e($item['category']??'')?></p><p><?=nl2br(e($item['content']??''))?></p>
 <?php elseif($current==='events'): ?><h3><?=e($item['title']??'')?></h3><p><?=e($item['date']??'')?> · <?=e($item['time']??'')?></p><p><?=nl2br(e($item['description']??''))?></p><details><summary>Editar evento</summary><form method="post" class="edit-form"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=e($item['id'])?>"><input name="title" value="<?=e($item['title']??'')?>" required><input type="date" name="date" value="<?=e($item['date']??'')?>" required><input type="time" name="time" value="<?=e($item['time']??'')?>"><textarea name="description"><?=e($item['description']??'')?></textarea><button class="btn secondary">Actualizar</button></form></details>
 <?php elseif($current==='recipes'): ?><h3><?=e($item['name']??'')?></h3><p><?=e($item['category']??'')?> · Ingredientes: <?=e($item['ingredients']??'')?></p><details><summary>Ver preparación</summary><p><?=nl2br(e($item['instructions']??''))?></p></details><button class="link-button" type="button" onclick="shareRecipe('<?=e($item['name']??'')?>')">Compartir</button>
 <?php endif ?>
 </div><div class="actions"><?php if($current==='tasks'): ?><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=e($item['id'])?>"><button class="btn secondary"><?=!empty($item['done'])?'Reabrir':'Completar'?></button></form><?php endif ?><form method="post" onsubmit="return confirm('¿Seguro que deseas eliminar este registro?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($item['id'])?>"><button class="btn danger">Eliminar</button></form></div></article><?php endforeach ?></div><?php endif ?></section>
